using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsInspectorOperations
{
    public void actions(RefCounted owner){var view=editor(owner);if(view==null)return;var physics=view.Get("physics").AsGodotObject();var panel=Panel(owner);var status=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart,Text=physics.Get("status").AsString()};panel.AddChild(status);panel.MoveChild(status,Math.Min(4,panel.GetChildCount()-1));status.AddThemeFontSizeOverride("font_size",12);physics.Connect("status_changed",new Callable(status,"set_text"));Update(owner,Callable.From(()=>status.Text=physics.Get("status").AsString()));var controls=new HFlowContainer();panel.AddChild(controls);foreach(string name in new[]{"Bake…","Clear cache","Recalculate","Freeze"}){string action=name;var button=new Button{Text=action};controls.AddChild(button);button.Pressed+=()=>this.action(owner,action,button,status);}var actor=Actor(owner);if(_growth.data(actor)!=null){var clear=new Button{Text="Clear bake"};controls.AddChild(clear);clear.Pressed+=()=>{var before=_settings.authored(actor);var after=before.Duplicate(true);after["mode"]=Get(before["bake"].AsGodotDictionary(),"source_mode",1).AsInt32();after["bake"]=new Settings();var model=Model(owner);var history=model.Get("history").As<UndoRedo>();var action=new PhysicsSettingsHistoryAction(model,actor,before,after);history.CreateAction("Clear growth bake");history.AddDoMethod(new Callable(action,nameof(PhysicsSettingsHistoryAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(PhysicsSettingsHistoryAction.restore_before)));history.AddDoReference(action);history.CommitAction();};}}
    public void action(RefCounted owner,string action,Button button,Label status)
    {
        var view=editor(owner);if(view==null)return;var physics=view.Get("physics").AsGodotObject();var actor=Actor(owner);if(action=="Freeze"){physics.Call("freeze",Model(owner),actor);return;}var host=Host(owner);if(action=="Bake…"&&(_growth.data(actor)!=null||Initial(owner)["type"].AsInt32()==9)){var control=GD.Load<GDScript>("res://scripts/actors/physics/destruction/destruction_workflow_control.gd").New().As<Node>();host.AddChild(control);control.Set("host",host);control.Set("actor",actor);control.Set("status",status);control.Call("bake_dialog",view);var dialog=control.FindChild("DestructionBakeDialog",true,false);if(dialog!=null)dialog.Connect(Node.SignalName.TreeExited,new Callable(control,"queue_free"));return;}if(action is "Clear cache" or "Recalculate"){var settings=_settings.authored(actor);if(action=="Recalculate"&&settings["mode"].AsInt32()==4)change(owner,"mode",Get(settings["bake"].AsGodotDictionary(),"source_mode",1).AsInt32(),true);physics.Set("signature","");physics.Call("mark_dirty");view.Call("_evaluate_runtimes");return;}var popup=new ConfirmationDialog{Title="Bake timeline physics",OkButtonText="Bake"};host.AddChild(popup);var fields=new VBoxContainer();popup.AddChild(fields);host.Call("_add_label",fields,"Scene start (seconds)");var start=Number();start.MinValue=0;start.MaxValue=86400;fields.AddChild(start);host.Call("_add_label",fields,"Scene end (seconds)");var end=Number();end.MinValue=.01;end.MaxValue=86400;end.SetValueNoSignal(view.Get("video_duration").AsDouble());fields.AddChild(end);popup.Confirmed+=()=>{button.Disabled=true;owner.Call("_await_bake",view,start.Value,end.Value,button,status,popup);};popup.Canceled+=popup.QueueFree;popup.PopupCentered(new Vector2I(300,180));
    }
    public void bake_finished(Button? button,Label? status,Window? popup,string error){if(GodotObject.IsInstanceValid(button))button!.Disabled=false;if(GodotObject.IsInstanceValid(status))status!.Text=error.Length>0?error:"Physics baked.";if(GodotObject.IsInstanceValid(popup))popup!.QueueFree();}
}
